INSERT INTO core_siteinstance (_seq, genome_id, start, end, strand)
SELECT
  'GTCAGTAA',
  (SELECT genome_id FROM core_genome WHERE genome_accession='NC_023064.1' LIMIT 1),
  317819,
  317826,
  1
WHERE NOT EXISTS (
  SELECT 1 FROM core_siteinstance
  WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_023064.1' LIMIT 1)
    AND start=317819 AND end=317826 AND strand=1
    AND _seq='GTCAGTAA'
);

INSERT INTO core_curation_siteinstance
  (curation_id, site_instance_id, annotated_seq, quantitative_value, site_type, TF_function, TF_type)
VALUES
  ((SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='41674119' LIMIT 1) ORDER BY curation_id DESC LIMIT 1),
   (SELECT site_id FROM core_siteinstance
        WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_023064.1' LIMIT 1)
          AND start=317819 AND end=317826 AND strand=1
          AND _seq='GTCAGTAA'
        ORDER BY site_id DESC LIMIT 1),
   'GTCAGTAA',
   0,
   'motif',
   'ACT',
   'MONOMER');

